cd /workspace && python3 -c "
import json
a=json.load(open('tmp/actual.json')); b=json.load(open('examples/expected.json'))
def walk(x,y,path=''):
    if type(x)!=type(y):
        print('TYPE',path,type(x),type(y)); return
    if isinstance(x,dict):
        for k in set(x)|set(y):
            if k not in x: print('MISSING-A',path+'/'+str(k))
            elif k not in y: print('EXTRA-A',path+'/'+str(k))
            else: walk(x[k],y[k],path+'/'+str(k))
    elif isinstance(x,list):
        if len(x)!=len(y): print('LEN',path,len(x),len(y)); return
        for i,(u,v) in enumerate(zip(x,y)): walk(u,v,path+'[%d]'%i)
    else:
        if x!=y: print('VAL',path,repr(x),repr(y))
walk(a,b)
"
